5	/**
6	 * Maps a canonical region (see {@link CityLocality}) to its IANA timezone via a fixed
7	 * table: NSW->Australia/Sydney, VIC->Australia/Melbourne, QLD->Australia/Brisbane. This
8	 * class owns only that mapping, keeping the timezone concern separate from region
9	 * resolution and reusable wherever a region is known.
10	 *
11	 * <p>A region with no known timezone (including {@link CityLocality#UNKNOWN} or a null
12	 * region) resolves to {@code null}.
13	 */
14	public final class RegionTimezone {
15	
16	    /** Region -> IANA timezone name. Anything not listed has no known timezone. */
17	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
18	            "NSW", "Australia/Sydney",
19	            "VIC", "Australia/Melbourne",
20	            "QLD", "Australia/Brisbane");
21	
22	    private RegionTimezone() {
23	    }
24	
25	    /**
26	     * @param region the canonical region, as resolved by {@link CityLocality}
27	     * @return the IANA timezone name for {@code region}, or {@code null} when it has no
28	     *         known timezone
29	     */
30	    public static String forRegion(String region) {
31	        return REGION_TIMEZONE.get(region);
32	    }
33	}
