1	package org.springframework.samples.petclinic.util;
2	
3	import java.util.Collection;
4	
5	/**
6	 * The owner member-id format, {@code <REGION><FY><HASH8><CHK>}: the canonical region (see
7	 * {@link CityLocality}), the two-digit {@link FiscalYear fiscal year}, the first eight
8	 * upper-case hex characters of a SHA-256 fingerprint, and a single {@link LuhnCheckDigit
9	 * Luhn check digit} computed over the digits of {@code <REGION><FY><HASH8>} (e.g.
10	 * {@code NSW261A2B3C4D7}). This class owns the format so the two concerns that depend on
11	 * it — composing the member-id at creation and reading the region back out for locality —
12	 * stay in step.
13	 */
14	public final class MemberId {
15	
16	    private static final char DEDUP_SEPARATOR = '-';
17	
18	    private MemberId() {
19	    }
20	
21	    /**
22	     * Composes a member-id from its region, fiscal-year and hash components, appending the
23	     * Luhn check digit computed over the digits of {@code <REGION><FY><HASH8>}.
24	     *
25	     * @param region          the canonical region
26	     * @param shortFiscalYear the two-digit fiscal year (0-99)
27	     * @param hash8           the eight-character hash
28	     * @return the {@code <REGION><FY><HASH8><CHK>} member-id
29	     */
30	    public static String of(String region, int shortFiscalYear, String hash8) {
31	        String body = String.format("%s%02d%s", region, shortFiscalYear, hash8);
32	        return body + LuhnCheckDigit.of(body);
33	    }
34	
35	    /**
36	     * De-duplicates a member-id against the ids already in use. If the id is unused it is
37	     * returned unchanged; otherwise {@code -<n>} is appended with the smallest {@code n} of
38	     * two or more that yields an id not already taken.
39	     *
40	     * @param memberId the composed member-id
41	     * @param existing the member-ids already in use
42	     * @return the {@code memberId}, or a {@code <memberId>-<n>} variant unique among
43	     *         {@code existing}
44	     */
45	    public static String deduplicate(String memberId, Collection<String> existing) {
46	        String candidate = memberId;
47	        for (int n = 2; existing.contains(candidate); n++) {
48	            candidate = memberId + DEDUP_SEPARATOR + n;
49	        }
50	        return candidate;
51	    }
52	
53	    /**
54	     * The region component of a member-id, i.e. the leading letters before the fiscal-year
55	     * digits. Robust to the {@code -<n>} de-duplication suffix, which sits after the region.
56	     *
57	     * @param memberId a member-id, or {@code null}
58	     * @return the region, or {@code null} when the id is absent or has no region part
59	     */
60	    public static String regionOf(String memberId) {
61	        if (memberId == null) {
62	            return null;
63	        }
64	        int end = 0;
65	        while (end < memberId.length() && !Character.isDigit(memberId.charAt(end))) {
66	            end++;
67	        }
68	        return end > 0 ? memberId.substring(0, end) : null;
69	    }
70	}
