1	package org.springframework.samples.petclinic.util;
2	
3	import java.util.Set;
4	
5	/**
6	 * Classifies an owner into a market segment formatted {@code <TIER>_<AREA>}, one of
7	 * {@code PREMIUM_METRO}, {@code PREMIUM_REGIONAL}, {@code STANDARD_METRO} or
8	 * {@code STANDARD_REGIONAL}.
9	 *
10	 * <p>The tier is {@code PREMIUM} when the membership level is 3 or more, otherwise
11	 * {@code STANDARD}. The area is {@code METRO} when the locality is a known region
12	 * (NSW, VIC or QLD), otherwise {@code REGIONAL}. This class owns only that
13	 * classification, keeping it separate from how the membership level and locality are
14	 * derived (see {@link CityLocality}).
15	 */
16	public final class OwnerSegment {
17	
18	    /** Membership level at or above which an owner is {@code PREMIUM} rather than {@code STANDARD}. */
19	    private static final int PREMIUM_MIN_LEVEL = 3;
20	
21	    /** Localities treated as {@code METRO}; any other locality is {@code REGIONAL}. */
22	    private static final Set<String> METRO_REGIONS = Set.of("NSW", "VIC", "QLD");
23	
24	    private OwnerSegment() {
25	    }
26	
27	    /**
28	     * @param membershipLevel the owner's membership level
29	     * @param locality        the owner's locality, as resolved by {@link CityLocality}
30	     * @return the {@code <TIER>_<AREA>} segment
31	     */
32	    public static String of(int membershipLevel, String locality) {
33	        String tier = membershipLevel >= PREMIUM_MIN_LEVEL ? "PREMIUM" : "STANDARD";
34	        String area = METRO_REGIONS.contains(locality) ? "METRO" : "REGIONAL";
35	        return tier + "_" + area;
36	    }
37	}
