14	
15	    private Sha256() {
16	    }
17	
18	    /**
19	     * The first {@code length} upper-case hexadecimal characters of the SHA-256 digest of
20	     * the UTF-8 bytes of {@code value}.
21	     *
22	     * @param value  the string to hash
23	     * @param length the number of leading hex characters to return
24	     * @return {@code length} upper-case hex characters
25	     */
26	    public static String upperHexPrefix(String value, int length) {
27	        byte[] digest = digest(value);
28	        StringBuilder hex = new StringBuilder(length);
29	        for (int i = 0; hex.length() < length; i++) {
30	            hex.append(String.format(Locale.ROOT, "%02X", digest[i]));
31	        }
32	        return hex.substring(0, length);
33	    }
34	
35	    /**
36	     * The full SHA-256 digest of the UTF-8 bytes of {@code value} rendered as 64 lower-case
37	     * hexadecimal characters.
38	     *
39	     * @param value the string to hash
40	     * @return 64 lower-case hex characters
41	     */
42	    public static String lowerHex(String value) {
43	        byte[] digest = digest(value);
44	        StringBuilder hex = new StringBuilder(digest.length * 2);
45	        for (byte b : digest) {
46	            hex.append(String.format(Locale.ROOT, "%02x", b));
47	        }
48	        return hex.toString();
49	    }
50	
51	    private static byte[] digest(String value) {
52	        try {
53	            return MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
54	        }
55	        catch (NoSuchAlgorithmException ex) {
56	            throw new IllegalStateException("SHA-256 is required but unavailable", ex);
57	        }
58	    }
59	}
