55	/**
56	 * The owner member-id format, {@code <REGION><FY><HASH8><CHK>}: the canonical region (see
57	 * {@link CityLocality}), the two-digit {@link FiscalYear fiscal year}, the first eight
58	 * upper-case hex characters of a SHA-256 fingerprint, and a single {@link LuhnCheckDigit
59	 * Luhn check digit} computed over the digits of {@code <REGION><FY><HASH8>} (e.g.
60	 * {@code NSW261A2B3C4D7}). This class owns the format so the two concerns that depend on
61	 * it — composing the member-id at creation and reading the region back out for locality —
62	 * stay in step.
63	 */
64	public final class MemberId {
65	
66	    private static final char DEDUP_SEPARATOR = '-';
67	
68	    private MemberId() {
69	    }
70	
71	    /**
72	     * Composes a member-id from its region, fiscal-year and hash components, appending the
73	     * Luhn check digit computed over the digits of {@code <REGION><FY><HASH8>}.
74	     *
75	     * @param region          the canonical region
76	     * @param shortFiscalYear the two-digit fiscal year (0-99)
77	     * @param hash8           the eight-character hash
78	     * @return the {@code <REGION><FY><HASH8><CHK>} member-id
79	     */
80	    public static String of(String region, int shortFiscalYear, String hash8) {
81	        String body = String.format("%s%02d%s", region, shortFiscalYear, hash8);
82	        return body + LuhnCheckDigit.of(body);
83	    }
84	
85	    /**
86	     * De-duplicates a member-id against the ids already in use. If the id is unused it is
87	     * returned unchanged; otherwise {@code -<n>} is appended with the smallest {@code n} of
88	     * two or more that yields an id not already taken.
89	     *
90	     * @param memberId the composed member-id
91	     * @param existing the member-ids already in use
92	     * @return the {@code memberId}, or a {@code <memberId>-<n>} variant unique among
93	     *         {@code existing}
94	     */
95	    public static String deduplicate(String memberId, Collection<String> existing) {
96	        String candidate = memberId;
97	        for (int n = 2; existing.contains(candidate); n++) {
98	            candidate = memberId + DEDUP_SEPARATOR + n;
99	        }
100	        return candidate;
101	    }
102	
103	    /**
104	     * The region component of a member-id, i.e. the leading letters before the fiscal-year
105	     * digits. Robust to the {@code -<n>} de-duplication suffix, which sits after the region.
106	     *
107	     * @param memberId a member-id, or {@code null}
108	     * @return the region, or {@code null} when the id is absent or has no region part
109	     */
110	    public static String regionOf(String memberId) {
111	        if (memberId == null) {
112	            return null;
113	        }
114	        int end = 0;
115	        while (end < memberId.length() && !Character.isDigit(memberId.charAt(end))) {
116	            end++;
117	        }
118	        return end > 0 ? memberId.substring(0, end) : null;
119	    }
120	}
