122	package org.springframework.samples.petclinic.util;
123	
124	import java.nio.charset.StandardCharsets;
125	import java.security.MessageDigest;
126	import java.security.NoSuchAlgorithmException;
127	import java.util.Locale;
128	
129	/**
130	 * SHA-256 hashing rendered as hexadecimal. Kept separate from any one caller so the
131	 * digest algorithm is defined once and reused wherever a stable hex fingerprint of a
132	 * string is needed (e.g. the hash component of an owner's customer code).
133	 */
134	public final class Sha256 {
135	
136	    private Sha256() {
137	    }
138	
139	    /**
140	     * The first {@code length} upper-case hexadecimal characters of the SHA-256 digest of
141	     * the UTF-8 bytes of {@code value}.
142	     *
143	     * @param value  the string to hash
144	     * @param length the number of leading hex characters to return
145	     * @return {@code length} upper-case hex characters
146	     */
147	    public static String upperHexPrefix(String value, int length) {
148	        byte[] digest = digest(value);
149	        StringBuilder hex = new StringBuilder(length);
150	        for (int i = 0; hex.length() < length; i++) {
151	            hex.append(String.format(Locale.ROOT, "%02X", digest[i]));
152	        }
153	        return hex.substring(0, length);
154	    }
155	
156	    /**
157	     * The full SHA-256 digest of the UTF-8 bytes of {@code value} rendered as 64 lower-case
158	     * hexadecimal characters.
159	     *
160	     * @param value the string to hash
161	     * @return 64 lower-case hex characters
162	     */
163	    public static String lowerHex(String value) {
164	        byte[] digest = digest(value);
165	        StringBuilder hex = new StringBuilder(digest.length * 2);
166	        for (byte b : digest) {
167	            hex.append(String.format(Locale.ROOT, "%02x", b));
168	        }
169	        return hex.toString();
170	    }
171	
172	    private static byte[] digest(String value) {
173	        try {
174	            return MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
175	        }
176	        catch (NoSuchAlgorithmException ex) {
177	            throw new IllegalStateException("SHA-256 is required but unavailable", ex);
178	        }
179	    }
180	}
