604	    /**
605	     * The owner's membership points, from 0 upwards: starts at 0, gains 2 when this owner
606	     * has an email address, gains 1 when this owner had no namesakes at creation
607	     * ({@code namesakeCount} is 0), gains 2 when this owner's household has 3 or more
608	     * members, and gains 3 once this owner's tenure spans at least one elapsed fiscal year.
609	     * A newly created owner has zero tenure, so it never earns those points at creation.
610	     * Derived from stored state, never persisted.
611	     */
612	    public int getMembershipPoints() {
613	        int points = 0;
614	        if (hasEmail()) {
615	            points += 2;
616	        }
617	        if (Integer.valueOf(0).equals(this.namesakeCount)) {
618	            points += 1;
619	        }
620	        if (this.householdSize != null && this.householdSize >= 3) {
621	            points += 2;
622	        }
623	        if (getTenureFiscalYears() >= 1) {
624	            points += 3;
625	        }
626	        return points;
627	    }
