629	    /**
630	     * The owner's fiscal year: the {@code FY<YY>} label (fiscal year starting 1 July,
631	     * identified by its ending calendar year) of the {@code registrationDate}, or
632	     * {@code null} when no registration date is recorded. Derived from stored state, never
633	     * persisted.
634	     */
635	    public String getFiscalYear() {
636	        return this.registrationDate == null ? null : FiscalYear.labelOf(this.registrationDate);
637	    }
