639	    /**
640	     * The owner's membership level, from 1 to 4: derived from {@link #getMembershipPoints()}
641	     * as level 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6 or more, then capped at
642	     * the {@link #getMembershipLevelCap() membership level cap} when one applies. Derived from
643	     * stored state, never persisted.
644	     */
645	    public int getMembershipLevel() {
646	        int level = uncappedMembershipLevel();
647	        return this.membershipLevelCap == null ? level : Math.min(level, this.membershipLevelCap);
648	    }
649	
650	    private int uncappedMembershipLevel() {
651	        int points = getMembershipPoints();
652	        if (points <= 1) {
653	            return 1;
654	        }
655	        if (points <= 3) {
656	            return 2;
657	        }
658	        if (points <= 5) {
659	            return 3;
660	        }
661	        return 4;
662	    }
