664	    /**
665	     * The owner's tenure in elapsed fiscal years: the number of fiscal years (each
666	     * starting 1 July) between the {@code registrationDate} and the current server date, or
667	     * 0 when no registration date is recorded. Never negative in practice, since a future
668	     * registration date is rejected at creation.
669	     */
670	    private int getTenureFiscalYears() {
671	        if (this.registrationDate == null) {
672	            return 0;
673	        }
674	        return FiscalYear.elapsed(this.registrationDate, LocalDate.now());
675	    }
