706	    public String getIdentityKey() {
707	        String telephonePart = this.telephone == null ? "" : this.telephone;
708	        String emailPart = hasEmail() ? this.email.toLowerCase(Locale.ROOT) : "";
709	        String namePart = Soundex.of(getLastName());
710	        return Sha256.lowerHex(telephonePart + "|" + emailPart + "|" + namePart);
711	    }
