758	     */
759	    public Pet getPet(String name, boolean ignoreNew) {
760	        name = name.toLowerCase();
761	        for (Pet pet : getPetsInternal()) {
762	            if (!ignoreNew || !pet.isNew()) {
763	                String compName = pet.getName();
764	                compName = compName.toLowerCase();
765	                if (compName.equals(name)) {
766	                    return pet;
767	                }
768	            }
769	        }
770	        return null;
771	    }
