841	package org.springframework.samples.petclinic.rest.function.owner;
842	
843	/**
844	 * Immutable structured audit event marking a successful owner creation, serialized to the
845	 * canonical JSON object
846	 * {@code {"seq":..,"ownerId":..,"memberId":..,"membershipLevel":..,"event":"OWNER_CREATED"}}.
847	 *
848	 * <p>The {@code memberId} field carries the owner's <em>current primary identifier</em>
849	 * (see {@link org.springframework.samples.petclinic.model.Owner#getPrimaryIdentifier()}).
850	 *
851	 * <p>Emitted by {@link AuditOwnerCreated}; {@code seq} comes from {@link OwnerCreatedEventSequence}
852	 * and increases monotonically across creates.
853	 */
854	public record OwnerCreatedEvent(long seq, int ownerId, String memberId, int membershipLevel) {
855	
856	    /** The event marker every serialized event carries. */
857	    public static final String EVENT = "OWNER_CREATED";
858	
859	    /** This event as its canonical JSON object, keys in the documented order. */
860	    public String toJson() {
861	        return "{"
862	                + "\"seq\":" + this.seq + ","
863	                + "\"ownerId\":" + this.ownerId + ","
864	                + "\"memberId\":" + quote(this.memberId) + ","
865	                + "\"membershipLevel\":" + this.membershipLevel + ","
866	                + "\"event\":" + quote(EVENT)
867	                + "}";
868	    }
869	
870	    private static String quote(String value) {
871	        if (value == null) {
872	            return "null";
873	        }
874	        StringBuilder sb = new StringBuilder(value.length() + 2).append('"');
875	        for (int i = 0; i < value.length(); i++) {
876	            char c = value.charAt(i);
877	            switch (c) {
878	                case '"' -> sb.append("\\\"");
879	                case '\\' -> sb.append("\\\\");
880	                case '\n' -> sb.append("\\n");
881	                case '\r' -> sb.append("\\r");
882	                case '\t' -> sb.append("\\t");
883	                default -> {
884	                    if (c < 0x20) {
885	                        sb.append(String.format("\\u%04x", (int) c));
886	                    }
887	                    else {
888	                        sb.append(c);
889	                    }
890	                }
891	            }
892	        }
893	        return sb.append('"').toString();
894	    }
895	}
