package org.springframework.samples.petclinic.util;

import java.util.Map;

/**
 * Resolves an owner's locality (the canonical region). The postcode range is preferred
 * ({@link Postcodes#regionForPostcode(String)}); only when the postcode is absent or in
 * no known range does resolution fall back to a fixed city-to-region table:
 * Sydney->NSW, Melbourne->VIC, Brisbane->QLD.
 *
 * <p>Cities not in the table have no known region and resolve to {@code "UNKNOWN"}.
 */
public final class CityLocality {

    /** City -> canonical region. Anything not listed resolves to {@link #UNKNOWN}. */
    private static final Map<String, String> CITY_REGION = Map.of(
            "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");

    /** The locality returned for a city with no known region. */
    public static final String UNKNOWN = "UNKNOWN";

    private CityLocality() {
    }

    /**
     * @param city the owner's city, as stored
     * @return the canonical region for {@code city}, or {@code "UNKNOWN"} when it is
     *         not in the table (including a null city)
     */
    public static String forCity(String city) {
        return CITY_REGION.getOrDefault(city, UNKNOWN);
    }

    /**
     * Resolves the locality preferring the postcode range, disambiguating cities that
     * share a name. Falls back to {@link #forCity(String)} when the postcode is absent
     * or in no known range.
     *
     * @param postcode the owner's postcode, as stored (may be null)
     * @param city     the owner's city, as stored
     * @return the region derived from the postcode, else from the city, else
     *         {@code "UNKNOWN"}
     */
    public static String forPostcodeOrCity(String postcode, String city) {
        String region = Postcodes.regionForPostcode(postcode);
        return region != null ? region : forCity(city);
    }
}
==== util/MemberId ====
package org.springframework.samples.petclinic.util;

import java.util.Collection;

/**
 * The owner member-id format, {@code <REGION><FY><HASH8><CHK>}: the canonical region (see
 * {@link CityLocality}), the two-digit {@link FiscalYear fiscal year}, the first eight
 * upper-case hex characters of a SHA-256 fingerprint, and a single {@link LuhnCheckDigit
 * Luhn check digit} computed over the digits of {@code <REGION><FY><HASH8>} (e.g.
 * {@code NSW261A2B3C4D7}). This class owns the format so the two concerns that depend on
 * it — composing the member-id at creation and reading the region back out for locality —
 * stay in step.
 */
public final class MemberId {

    private static final char DEDUP_SEPARATOR = '-';

    private MemberId() {
    }

    /**
     * Composes a member-id from its region, fiscal-year and hash components, appending the
     * Luhn check digit computed over the digits of {@code <REGION><FY><HASH8>}.
     *
     * @param region          the canonical region
     * @param shortFiscalYear the two-digit fiscal year (0-99)
     * @param hash8           the eight-character hash
     * @return the {@code <REGION><FY><HASH8><CHK>} member-id
     */
    public static String of(String region, int shortFiscalYear, String hash8) {
        String body = String.format("%s%02d%s", region, shortFiscalYear, hash8);
        return body + LuhnCheckDigit.of(body);
    }

    /**
     * De-duplicates a member-id against the ids already in use. If the id is unused it is
     * returned unchanged; otherwise {@code -<n>} is appended with the smallest {@code n} of
     * two or more that yields an id not already taken.
     *
     * @param memberId the composed member-id
     * @param existing the member-ids already in use
     * @return the {@code memberId}, or a {@code <memberId>-<n>} variant unique among
     *         {@code existing}
     */
    public static String deduplicate(String memberId, Collection<String> existing) {
        String candidate = memberId;
        for (int n = 2; existing.contains(candidate); n++) {
            candidate = memberId + DEDUP_SEPARATOR + n;
        }
        return candidate;
    }

    /**
     * The region component of a member-id, i.e. the leading letters before the fiscal-year
     * digits. Robust to the {@code -<n>} de-duplication suffix, which sits after the region.
     *
     * @param memberId a member-id, or {@code null}
     * @return the region, or {@code null} when the id is absent or has no region part
     */
    public static String regionOf(String memberId) {
        if (memberId == null) {
            return null;
        }
        int end = 0;
        while (end < memberId.length() && !Character.isDigit(memberId.charAt(end))) {
            end++;
        }
        return end > 0 ? memberId.substring(0, end) : null;
    }
}
==== util/Sha256 ====
package org.springframework.samples.petclinic.util;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Locale;

/**
 * SHA-256 hashing rendered as hexadecimal. Kept separate from any one caller so the
 * digest algorithm is defined once and reused wherever a stable hex fingerprint of a
 * string is needed (e.g. the hash component of an owner's customer code).
 */
public final class Sha256 {

    private Sha256() {
    }

    /**
     * The first {@code length} upper-case hexadecimal characters of the SHA-256 digest of
     * the UTF-8 bytes of {@code value}.
     *
     * @param value  the string to hash
     * @param length the number of leading hex characters to return
     * @return {@code length} upper-case hex characters
     */
    public static String upperHexPrefix(String value, int length) {
        byte[] digest = digest(value);
        StringBuilder hex = new StringBuilder(length);
        for (int i = 0; hex.length() < length; i++) {
            hex.append(String.format(Locale.ROOT, "%02X", digest[i]));
        }
        return hex.substring(0, length);
    }

    /**
     * The full SHA-256 digest of the UTF-8 bytes of {@code value} rendered as 64 lower-case
     * hexadecimal characters.
     *
     * @param value the string to hash
     * @return 64 lower-case hex characters
     */
    public static String lowerHex(String value) {
        byte[] digest = digest(value);
        StringBuilder hex = new StringBuilder(digest.length * 2);
        for (byte b : digest) {
            hex.append(String.format(Locale.ROOT, "%02x", b));
        }
        return hex.toString();
    }

    private static byte[] digest(String value) {
        try {
            return MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
        }
        catch (NoSuchAlgorithmException ex) {
            throw new IllegalStateException("SHA-256 is required but unavailable", ex);
        }
    }
}
