361	     * The id of the existing owner this owner possibly duplicates (same postcode and a
362	     * phonetically-equal last name but a different {@link #getIdentityKey() identity key}), or
363	     * null when it is not a possible duplicate. Captured at creation.
364	     */
365	    public Integer getPossibleDuplicateOf() {
366	        return this.possibleDuplicateOf;
367	    }
