387	    /**
388	     * The owner's locality: the canonical region carried in the {@code <REGION><FY><HASH8><CHK>}
389	     * member-id, i.e. the same region-and-hash identity used everywhere else. That region was
390	     * derived at creation by preferring the postcode range (NSW 2000-2099, VIC 3000-3099,
391	     * QLD 4000-4099), falling back to the fixed city-to-region table (Sydney->NSW,
392	     * Melbourne->VIC, Brisbane->QLD) when the postcode is absent or in no known range, or
393	     * {@code "UNKNOWN"} otherwise. For an owner with no member-id the region is derived directly
394	     * from the stored postcode and city. Derived from stored state, never persisted.
395	     */
396	    public String getLocality() {
397	        String region = MemberId.regionOf(this.memberId);
398	        return region != null ? region : CityLocality.forPostcodeOrCity(this.postcode, this.city);
399	    }
400	
401	    /**
402	     * The owner's market segment, formatted {@code <TIER>_<AREA>}: the tier is
403	     * {@code PREMIUM} when {@link #getMembershipLevel() membership level} is 3 or more,
404	     * otherwise {@code STANDARD}; the area is {@code METRO} when {@link #getLocality()
405	     * locality} is a known region (NSW, VIC or QLD), otherwise {@code REGIONAL}. One of
406	     * {@code PREMIUM_METRO}, {@code PREMIUM_REGIONAL}, {@code STANDARD_METRO} or
407	     * {@code STANDARD_REGIONAL}. Derived from stored state, never persisted.
408	     */
409	    public String getOwnerSegment() {
410	        return OwnerSegment.of(getMembershipLevel(), getLocality());
411	    }
412	
413	    /**
414	     * The owner's timezone: the IANA name for this owner's {@link #getLocality() locality}
415	     * via the fixed region-to-timezone table (NSW->Australia/Sydney,
416	     * VIC->Australia/Melbourne, QLD->Australia/Brisbane), or {@code null} when the region
417	     * has no known timezone. Derived from stored state, never persisted.
418	     */
419	    public String getTimezone() {
420	        return RegionTimezone.forRegion(getLocality());
421	    }
422	
423	    /**
424	     * The owner's membership points, from 0 upwards: starts at 0, gains 2 when this owner
425	     * has an email address, gains 1 when this owner had no namesakes at creation
426	     * ({@code namesakeCount} is 0), gains 2 when this owner's household has 3 or more
427	     * members, and gains 3 once this owner's tenure spans at least one elapsed fiscal year.
428	     * A newly created owner has zero tenure, so it never earns those points at creation.
429	     * Derived from stored state, never persisted.
430	     */
431	    public int getMembershipPoints() {
432	        int points = 0;
433	        if (hasEmail()) {
434	            points += 2;
435	        }
436	        if (Integer.valueOf(0).equals(this.namesakeCount)) {
437	            points += 1;
438	        }
439	        if (this.householdSize != null && this.householdSize >= 3) {
440	            points += 2;
441	        }
442	        if (getTenureFiscalYears() >= 1) {
443	            points += 3;
444	        }
445	        return points;
446	    }
447	
448	    /**
449	     * The owner's fiscal year: the {@code FY<YY>} label (fiscal year starting 1 July,
450	     * identified by its ending calendar year) of the {@code registrationDate}, or
451	     * {@code null} when no registration date is recorded. Derived from stored state, never
452	     * persisted.
453	     */
454	    public String getFiscalYear() {
455	        return this.registrationDate == null ? null : FiscalYear.labelOf(this.registrationDate);
456	    }
457	
458	    /**
459	     * The owner's membership level, from 1 to 4: derived from {@link #getMembershipPoints()}
460	     * as level 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6 or more, then capped at
461	     * the {@link #getMembershipLevelCap() membership level cap} when one applies. Derived from
462	     * stored state, never persisted.
463	     */
464	    public int getMembershipLevel() {
465	        int level = uncappedMembershipLevel();
466	        return this.membershipLevelCap == null ? level : Math.min(level, this.membershipLevelCap);
467	    }
468	
469	    private int uncappedMembershipLevel() {
470	        int points = getMembershipPoints();
471	        if (points <= 1) {
472	            return 1;
473	        }
474	        if (points <= 3) {
475	            return 2;
476	        }
477	        if (points <= 5) {
478	            return 3;
479	        }
480	        return 4;
481	    }
482	
483	    /**
484	     * The owner's tenure in elapsed fiscal years: the number of fiscal years (each
485	     * starting 1 July) between the {@code registrationDate} and the current server date, or
486	     * 0 when no registration date is recorded. Never negative in practice, since a future
487	     * registration date is rejected at creation.
488	     */
489	    private int getTenureFiscalYears() {
490	        if (this.registrationDate == null) {
491	            return 0;
492	        }
493	        return FiscalYear.elapsed(this.registrationDate, LocalDate.now());
494	    }
495	
496	    /**
497	     * The owner's preferred contact channel: {@code "EMAIL"} when an email address is
498	     * present, otherwise {@code "PHONE"}. Derived from stored state, never persisted.
499	     */
500	    public String getContactPreference() {
501	        return hasEmail() ? "EMAIL" : "PHONE";
502	    }
503	
504	    /**
505	     * Whether this owner warrants a closer look: {@code true} when any risk signal holds —
506	     * it is a {@link #isPossibleDuplicate() possible duplicate}, its email domain is
507	     * {@link DisposableEmailDomains#isDisposableAdjacent(String) disposable-adjacent}, or
508	     * its city was {@link #isCapacityWarning() over its soft capacity} at creation — and
509	     * {@code false} otherwise. Derived from stored state, never persisted.
510	     */
511	    public boolean getRiskFlag() {
512	        return isPossibleDuplicate()
513	            || DisposableEmailDomains.isDisposableAdjacent(this.email)
514	            || isCapacityWarning();
515	    }
516	
517	    /**
518	     * The owner's identity key: the 64-character lower-case SHA-256 hex of the normalized
519	     * telephone, the lower-cased email (or empty when absent) and the {@link Soundex Soundex}
520	     * code of the last name, joined by {@code '|'}. Two owners collide on this key only when
521	     * they share a telephone, an email and a phonetically-equal surname, so it is the single
522	     * fingerprint the create endpoint's duplicate check keys off. Derived from stored state,
523	     * never persisted.
524	     */
525	    public String getIdentityKey() {
526	        String telephonePart = this.telephone == null ? "" : this.telephone;
527	        String emailPart = hasEmail() ? this.email.toLowerCase(Locale.ROOT) : "";
528	        String namePart = Soundex.of(getLastName());
529	        return Sha256.lowerHex(telephonePart + "|" + emailPart + "|" + namePart);
530	    }
531	
532	    private boolean hasEmail() {
533	        return this.email != null && !this.email.isEmpty();
534	    }
535	
536	    protected Set<Pet> getPetsInternal() {
537	        if (this.pets == null) {
538	            this.pets = new HashSet<>();
539	        }
540	        return this.pets;
541	    }
542	
543	    protected void setPetsInternal(Set<Pet> pets) {
544	        this.pets = pets;
545	    }
546	
547	    public List<Pet> getPets() {
548	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
549	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
550	        return Collections.unmodifiableList(sortedPets);
551	    }
552	
553	    public void setPets(List<Pet> pets) {
554	        this.pets = new HashSet<>(pets);
555	    }
556	
557	    public void addPet(Pet pet) {
558	        getPetsInternal().add(pet);
559	        pet.setOwner(this);
560	    }
561	
562	    /**
563	     * Return the Pet with the given name, or null if none found for this Owner.
564	     *
565	     * @param name to test
566	     * @return true if pet name is already in use
567	     */
568	    public Pet getPet(String name) {
569	        return getPet(name, false);
570	    }
571	
572	    /**
573	     * Return the Pet with the given name, or null if none found for this Owner.
574	     *
575	     * @param name to test
576	     * @return true if pet name is already in use
577	     */
578	    public Pet getPet(String name, boolean ignoreNew) {
579	        name = name.toLowerCase();
580	        for (Pet pet : getPetsInternal()) {
581	            if (!ignoreNew || !pet.isNew()) {
582	                String compName = pet.getName();
583	                compName = compName.toLowerCase();
584	                if (compName.equals(name)) {
585	                    return pet;
586	                }
587	            }
588	        }
589	        return null;
590	    }
591	
592	    public Pet getPet(Integer petId) {
593	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
594	    }
595	
596	    @Override
597	    public String toString() {
598	        return new ToStringCreator(this)
599	
600	            .append("id", this.getId())
601	            .append("new", this.isNew())
602	            .append("lastName", this.getLastName())
603	            .append("firstName", this.getFirstName())
604	            .append("address", this.address)
605	            .append("city", this.city)
606	            .append("telephone", this.telephone)
607	            .toString();
608	    }
609	}
