     * The owner's preferred contact channel: {@code "EMAIL"} when an email address is
     * present, otherwise {@code "PHONE"}. Derived from stored state, never persisted.
     */
    public String getContactPreference() {
        return hasEmail() ? "EMAIL" : "PHONE";
    }

    /**
     * Whether this owner warrants a closer look: {@code true} when any risk signal holds —
     * it is a {@link #isPossibleDuplicate() possible duplicate}, its email domain is
     * {@link DisposableEmailDomains#isDisposableAdjacent(String) disposable-adjacent}, or
     * its city was {@link #isCapacityWarning() over its soft capacity} at creation — and
     * {@code false} otherwise. Derived from stored state, never persisted.
     */
    public boolean getRiskFlag() {
        return isPossibleDuplicate()
            || DisposableEmailDomains.isDisposableAdjacent(this.email)
            || isCapacityWarning();
    }

    /**
     * The owner's identity key: the 64-character lower-case SHA-256 hex of the fixed
     * {@link OwnerIdentityVersion#TAG version-2 tag}, the normalized telephone, the lower-cased
     * email (or empty when absent) and the {@link Soundex Soundex} code of the last name, joined
     * by {@code '|'}. The tag makes the version-2 key differ from its version-1 form. Two owners
     * collide on this key only when they share a telephone, an email and a phonetically-equal
     * surname, so it is the single fingerprint the create endpoint's duplicate check keys off.
     * Derived from stored state, never persisted.
     */
